const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/electronic_signatures/%7Belectronic_signature_id%7D',
  qs: {
    company_id: 'SOME_INTEGER_VALUE',
    project_id: 'SOME_INTEGER_VALUE',
    view: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/electronic_signatures/%7Belectronic_signature_id%7D?company_id=SOME_INTEGER_VALUE&project_id=SOME_INTEGER_VALUE&view=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/electronic_signatures',
